function togglePasswordVisibility() {
  const passwordInput = document.getElementById('password');
  const eyeIcon = document.getElementById('eyeIcon');
  if (passwordInput.type === 'password') {
    passwordInput.type = 'text';
    eyeIcon.textContent = 'visibility_off';
  } else {
    passwordInput.type = 'password';
    eyeIcon.textContent = 'visibility';
  }
}

function handleAuthSubmit() {
  const identifier = document.getElementById('identifier');
  const password = document.getElementById('password');
  let hasError = false;

  if (!identifier.value.trim()) {
    identifier.classList.add('shadow-[0_0_0_2px_#ffb4ab]');
    hasError = true;
  } else {
    identifier.classList.remove('shadow-[0_0_0_2px_#ffb4ab]');
  }

  if (!password.value.trim()) {
    password.classList.add('shadow-[0_0_0_2px_#ffb4ab]');
    hasError = true;
  } else {
    password.classList.remove('shadow-[0_0_0_2px_#ffb4ab]');
  }

  if (!hasError) {
    const submitBtn = document.getElementById('submitBtn');
    submitBtn.disabled = true;
    submitBtn.classList.add('opacity-70');
    submitBtn.innerHTML = '<span class="material-symbols-outlined text-[20px] animate-spin">refresh</span><span>Đang đăng nhập...</span>';

    setTimeout(() => {
      submitBtn.classList.remove('opacity-70');
      submitBtn.innerHTML = '<span class="material-symbols-outlined text-[20px]">check_circle</span><span>Thành công!</span>';
    }, 1200);
  }
}

