  ];

  let memeIndex = 0;
  let lastX = 0;
  let lastY = 0;
  let lastTime = 0;
  const distanceThreshold = 48; // minimum distance traveled to drop photo
  const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function getNextMeme() {
    const img = memeImages[memeIndex % memeImages.length];
    memeIndex++;
    return img;
  }

  function createPolaroidCard(x, y, vx = 0, vy = 0, customDelay = 0) {
    const card = document.createElement('div');
    card.className = 'meme-trail-card p-1 pb-3 rounded-lg bg-white/95 dark:bg-[#1a1b23]/95 backdrop-blur-md border border-[#d0bcff]/40 shadow-[0_12px_28px_rgba(0,0,0,0.65),0_0_12px_rgba(208,188,255,0.25)] flex flex-col items-center';

    // Random tilt between -18 and 18 deg
    const rot = (Math.random() * 32 - 16).toFixed(1);
    const width = Math.floor(Math.random() * 16) + 84; // 84px to 100px width
    card.style.width = width + 'px';
    card.style.left = (x - width / 2) + 'px';
    card.style.top = (y - (width * 0.6)) + 'px';

    // Inner image thumbnail and caption bar like a real polaroid
    const imgSrc = getNextMeme();
    card.innerHTML = `
      <div class="w-full aspect-[4/3] rounded overflow-hidden bg-black/60 relative">
        <img src="${imgSrc}" class="w-full h-full object-cover select-none pointer-events-none" alt="Meme thumbnail" loading="eager" />
      </div>
      <div class="w-full mt-1 px-1 flex items-center justify-between">
        <span class="w-8 h-1 bg-outline/25 rounded-full"></span>
        <span class="text-[8px] font-mono-tag text-outline/60 tracking-wider uppercase font-semibold">aura</span>
      </div>
    `;

    if (prefersReducedMotion) {
      card.style.transform = `scale(1) rotate(${rot}deg)`;
      card.style.opacity = '1';
      container.appendChild(card);
      setTimeout(() => {
        card.style.opacity = '0';
        setTimeout(() => card.remove(), 250);
      }, 1200);
      return;
    }

    // Initial state: dropping down / popping into position
    const initialScale = 0.55;
    card.style.transform = `translate3d(${vx * -8}px, ${vy * -8 - 14}px, 0) scale(${initialScale}) rotate(${-rot * 0.5}deg)`;
    card.style.opacity = '0';

    container.appendChild(card);

    // Force layout then animate in
    requestAnimationFrame(() => {
      card.style.opacity = '1';
      card.style.transform = `translate3d(${vx * 12}px, ${vy * 12}px, 0) scale(1) rotate(${rot}deg)`;
    });

    // After lifetime, smoothly shrink and fade away
    const lifeSpan = 1400 + Math.random() * 400 + customDelay;
    setTimeout(() => {
      card.style.opacity = '0';
      card.style.transform = `translate3d(${vx * 18}px, ${vy * 18 + 18}px, 0) scale(0.65) rotate(${rot * 1.3}deg)`;
      setTimeout(() => {
        if (card.parentNode) {
          card.remove();
        }
      }, 460);
    }, lifeSpan);
  }

  // Cursor move handler
  stage.addEventListener('pointermove', (e) => {
    const rect = stage.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const dist = Math.hypot(x - lastX, y - lastY);
    const now = Date.now();

    if (dist > distanceThreshold || (dist > 20 && now - lastTime > 180)) {
      const vx = (x - lastX) / (dist || 1);
      const vy = (y - lastY) / (dist || 1);
      createPolaroidCard(x, y, vx * 0.8, vy * 0.8);
      lastX = x;
      lastY = y;
      lastTime = now;
    }
  });

  // Stage Click: Fan-out burst of 5 polaroid meme photos
  stage.addEventListener('pointerdown', (e) => {
    // Don't trigger if clicked on an actual interactive link inside stage if any
    if (e.target.closest('a') || e.target.closest('button')) return;

    const rect = stage.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const burstCount = 5;
    const angleStep = (Math.PI * 2) / burstCount;
    const baseOffset = Math.random() * Math.PI;

    for (let i = 0; i < burstCount; i++) {
      const angle = baseOffset + i * angleStep;
      const radius = 24 + Math.random() * 20;
      const targetX = x + Math.cos(angle) * radius;
      const targetY = y + Math.sin(angle) * radius;
      const vx = Math.cos(angle) * 2;
      const vy = Math.sin(angle) * 2;

      setTimeout(() => {
        createPolaroidCard(targetX, targetY, vx, vy, i * 60);
      }, i * 35);
    }
  });
